action.command:
node -e "
const path = require('path');
const { execSync } = require('child_process');
const input = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const file = input.file || '';
const guestDir = path.join(input.workspaceRoot || '.', 'frontend-guest');
const staffDir = path.join(input.workspaceRoot || '.', 'frontend-staff');
const isGuest = file.includes('frontend-guest');
const isStaff = file.includes('frontend-staff');
const dirs = isGuest ? [guestDir] : isStaff ? [staffDir] : [guestDir, staffDir];
let passed = true;
for (const dir of dirs) {
  try {
    execSync('npx tsc --noEmit', { cwd: dir, stdio: 'pipe' });
    process.stdout.write(JSON.stringify({ message: 'tsc OK: ' + dir }) + '\n');
  } catch (e) {
    process.stderr.write('TypeScript errors in ' + dir + ':\n' + (e.stdout || e.stderr || e.message) + '\n');
    passed = false;
  }
}
process.exit(passed ? 0 : 1);
"
